# Решение задачи

Вот реализация трёх функций с тестами:

```python
def flatten(obj, parent_key=''):
    """Преобразует вложенный dict/list в плоский dict с dot-notation ключами."""
    items = []

    if isinstance(obj, dict):
        for k, v in obj.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, (dict, list)):
                items.extend(flatten(v, new_key).items())
            else:
                items.append((new_key, v))
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            new_key = f"{parent_key}.{i}"
            if isinstance(v, (dict, list)):
                items.extend(flatten(v, new_key).items())
            else:
                items.append((new_key, v))

    return dict(items)


def unflatten(flat_dict):
    """Восстанавливает вложенную структуру из плоского dict."""
    result = {}

    for key, value in flat_dict.items():
        parts = key.split('.')
        current = result

        # Проходим по всем частям ключа, кроме последней
        for part in parts[:-1]:
            if part.isdigit():
                idx = int(part)
                # Создаём список, если нужно
                if not isinstance(current, list):
                    current = []
                # Расширяем список, если индекс выходит за границы
                while len(current) <= idx:
                    current.append({})
                # Переходим к следующему уровню
                if not isinstance(current[idx], (dict, list)):
                    current[idx] = {}
                current = current[idx]
            else:
                if part not in current:
                    current[part] = {}
                current = current[part]

        # Устанавливаем финальное значение
        last_part = parts[-1]
        if last_part.isdigit():
            idx = int(last_part)
            if not isinstance(current, list):
                current = []
            while len(current) <= idx:
                current.append(None)
            current[idx] = value
        else:
            current[last_part] = value

    return result


def test_roundtrip():
    """Проверяет roundtrip для 5 различных структур."""
    test_cases = [
        # 1. Простой dict
        {"name": "Alice", "age": 30},

        # 2. Вложенный на 3 уровня
        {"a": {"b": {"c": {"d": "value"}}}},

        # 3. С массивами
        {"users": [{"name": "Bob"}, {"name": "Carol"}], "count": 2},

        # 4. С None/null значениями
        {"a": None, "b": {"c": None, "d": [None, 1, None]}},

        # 5. С пустыми объектами
        {"empty": {}, "nested": {"also_empty": {}}, "list_empty": []},
    ]

    print("=" * 60)
    print("Тестирование roundtrip: flatten → unflatten")
    print("=" * 60)

    for i, original in enumerate(test_cases, 1):
        flat = flatten(original)
        restored = unflatten(flat)

        # Проверяем равенство
        is_equal = restored == original

        print(f"\nТест {i}: {'✓ ПРОЙДЕН' if is_equal else '✗ ПРОВАЛЕН'}")
        print(f"  Оригинал:  {original}")
        print(f"  Flat:      {flat}")
        print(f"  Восстанов: {restored}")

    print("\n" + "=" * 60)
    print("Все тесты завершены!")
    print("=" * 60)


if __name__ == "__main__":
    test_roundtrip()
```

